import app from 'flarum/admin/app';
import isExtensionEnabled from 'flarum/admin/utils/isExtensionEnabled';
/** Why points are off: no Gamification at all, or one without point grants. */
export const pointsHint = () => isExtensionEnabled('fof-gamification') ? 'admin.needs_points' : 'admin.needs_gamification';
const base = () => app.forum.attribute('apiUrl') + '/onramp-admin';

/** The editor's state, shared by the page and its modal. */
export const store = {
  listing: null
};
export function load() {
  return app.request({
    method: 'GET',
    url: base() + '/steps'
  }).then(res => store.listing = res);
}
export function save(id, attributes) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: base() + '/steps' + (id ? `/${id}` : ''),
    body: {
      attributes
    }
  }).then(res => store.listing = res);
}
export function remove(id) {
  return app.request({
    method: 'DELETE',
    url: base() + `/steps/${id}`
  }).then(load);
}
export function order(ids) {
  return app.request({
    method: 'POST',
    url: base() + '/order',
    body: {
      ids
    }
  }).then(res => store.listing = res);
}
export function importSteps(steps, replace) {
  return app.request({
    method: 'POST',
    url: base() + '/import',
    body: {
      steps,
      replace
    }
  }).then(res => store.listing = res);
}
export function funnel(weeks) {
  return app.request({
    method: 'GET',
    url: base() + '/funnel',
    params: {
      weeks
    }
  }).then(res => res.data);
}
export function startExisting(days) {
  return app.request({
    method: 'POST',
    url: base() + '/start-existing',
    body: {
      days
    }
  }).then(res => res.data);
}
let badges = null;

/** FoF Badges' own list, fetched once per admin visit. */
export function loadBadges() {
  badges ??= app.request({
    method: 'GET',
    url: app.forum.attribute('apiUrl') + '/badges',
    params: {
      page: {
        limit: 50
      }
    }
  }).then(res => res.data.map(b => ({
    id: b.id,
    name: b.attributes.name,
    icon: b.attributes.icon
  }))).catch(() => []);
  return badges;
}
